effect.shader:
const int TAPS = 12;
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  vec3 acc = vec3(0.0);
  for (int i = 0; i < TAPS; i++){
    float ang = float(i) * 6.2831853 / float(TAPS);
    vec2 o = vec2(cos(ang), sin(ang)) * radius;
    vec4 s = texture2DCv(inputImg.texture, uv + o);
    vec3 sc = s.rgb / max(s.a, 1e-4);
    float l = gmLum(sc);
    acc += sc * max(l - threshold, 0.0);
  }
  acc /= float(TAPS);
  vec3 col = c + acc * intensity * mixAmt;
  gl_FragColor = vec4(clamp(col, 0.0, 1.0) * a, a);
}
